list_blog_categories.code:
var response = await client.BlogCategories.ListBlogCategoriesAsync(
    new Dictionary<string, object?> { ["limit"] = 20, ["offset"] = 0 });
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
foreach (var blogCategory in ((IReadOnlyList<object?>)body["blog_categories"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{blogCategory["id"]} {blogCategory["name"]} {blogCategory["url"]}");
var pagination = (IReadOnlyDictionary<string, object?>)body["pagination"]!;
Console.WriteLine($"{pagination["total"]} {pagination["has_next"]}");

